# Collapsible per-card guidance: a small muted toggle that expands help inline.
# Uses a native <details> element, so it needs no JS and costs no layout space
# when collapsed (the default).
card_help <- function(...) {
  tags$details(
    class = "small text-body-secondary mb-2",
    tags$summary(
      class = "text-primary",
      style = "cursor: pointer;",
      "How to read this"
    ),
    div(class = "pt-2", ...)
  )
}

# --- Bring-your-own-data drawer --------------------------------------------
# Uploads live in a right-side offcanvas rather than inline in the controls, so
# the file pickers get room and a clear column spec. The drawer stays mounted
# (offcanvas only toggles visibility), so a validated upload isn't lost when it
# is closed. Selecting "Upload your own…" opens it (via the hidden trigger the
# server clicks); the visible controls button reopens it to change files.
de_upload_offcanvas <- div(
  class = "offcanvas offcanvas-start",
  tabindex = "-1",
  id = "de-upload-canvas",
  `aria-labelledby` = "de-upload-canvas-label",
  style = "width: 460px;",
  div(
    class = "offcanvas-header",
    tags$h5(
      class = "offcanvas-title",
      id = "de-upload-canvas-label",
      "Upload your own DE dataset"
    ),
    tags$button(
      type = "button",
      class = "btn-close",
      `data-bs-dismiss` = "offcanvas",
      `aria-label` = "Close"
    )
  ),
  div(
    class = "offcanvas-body",
    div(
      class = "small",
      tags$p(
        "Provide three CSV files matching the DE data contract. Column names",
        "must match exactly (case-sensitive) - the dataset is rejected",
        "otherwise, with the reason shown below."
      ),
      tags$ul(
        class = "mb-2 ps-3",
        tags$li(
          tags$code("de_results.csv"),
          " - one row per gene. Required columns: ",
          tags$code(toString(de_results_required)),
          "."
        ),
        tags$li(
          tags$code("expression.csv"),
          " - a ",
          tags$code("gene"),
          " column plus one numeric column per sample (log2-normalised)."
        ),
        tags$li(
          tags$code("metadata.csv"),
          " - one row per sample. Required columns: ",
          tags$code(toString(de_metadata_required)),
          "."
        )
      ),
      tags$p(
        class = "text-body-secondary",
        "Expression sample columns must match the metadata sample values, and",
        "every gene in de_results must appear in the expression matrix."
      )
    ),
    tags$hr(),
    data_upload_validate_ui("de_upload", de_upload_files)
  )
)

# Hidden trigger the server "clicks" to open the drawer when the dataset select
# switches to "Upload your own…", plus a hidden→revert bridge: when the drawer
# is closed with no valid upload, tell the server so it can restore the previous
# dataset instead of leaving the app on an empty "__upload__" selection.
de_upload_glue <- tagList(
  tags$button(
    id = "de-upload-trigger",
    class = "d-none",
    type = "button",
    `data-bs-toggle` = "offcanvas",
    `data-bs-target` = "#de-upload-canvas"
  ),
  tags$script(HTML(paste0(
    "Shiny.addCustomMessageHandler('open_de_upload', function(x){",
    "var b=document.getElementById('de-upload-trigger');",
    "if(b){b.click();}});",
    "document.addEventListener('DOMContentLoaded', function(){",
    "var el=document.getElementById('de-upload-canvas');",
    "if(el){el.addEventListener('hidden.bs.offcanvas', function(){",
    "Shiny.setInputValue('de_upload_closed', Date.now());});}});"
  )))
)

