server <- function(input, output, session) {
  # --- Guided demo tour (the "Demo" button in the navbar) -----------------
  # Walks a first-time user through the whole app: the input controls, then each
  # analysis card (highlighting its header), the assistant, and finally the
  # About page (cicerone switches to that nav tab for the last step).
  demo_guide <- cicerone::Cicerone$new(overlay_click_next = TRUE)$step(
    "hdr-controls",
    "1. Choose your data",
    paste(
      "Start here: pick a dataset (the lung LUAD vs LUSC set loads by",
      "default) and set the fold-change and significance thresholds. These",
      "are global and drive every view below."
    )
  )$step(
    "dataset_card",
    "About this dataset",
    "A quick summary of the loaded cohort: design, sample counts, source, and a link to the data portal."
  )$step(
    "hdr-pca",
    "PCA",
    "A principal-components overview of the samples. Colour by a metadata column (e.g. group) to see how they separate."
  )$step(
    "hdr-table",
    "Results table",
    "Every gene's fold change and significance. Select rows to drive the Heatmap; click a row to focus that gene."
  )$step(
    "hdr-detail",
    "Gene detail",
    "The focused gene's expression across sample groups, with a group-comparison test."
  )$step(
    "hdr-volcano",
    "Volcano",
    "Effect size vs significance; colour marks up / down / not-significant. Click a point to focus that gene."
  )$step(
    "hdr-heatmap",
    "Heatmap",
    "Expression of the selected genes. Its gene and display controls live under Heatmap in the left rail."
  )$step(
    "hdr-enrichment",
    "Enrichment",
    "MSigDB Hallmark pathways over-represented among the significant genes, as a dot plot and a table."
  )$step(
    "tour-assistant",
    "AI assistant",
    "Bring your own API key and ask about any view, or have it drive the controls for you."
  )$step(
    "a.nav-link[data-value='About']",
    "Learn more",
    "Finally, open the About page (this tab) for full data provenance, methods, and citations. That's the tour!",
    is_id = FALSE
  )
  observeEvent(input$demo, demo_guide$init()$start())

  # One shared dataset: a bundled contract dir, or the user's uploaded CSVs
  # (validated through the same contract).
  uploaded <- data_upload_validate_server(
    "de_upload",
    reader = read_de_dataset,
    files = de_upload_files
  )
  dataset <- reactive({
    if (identical(input$dataset, "__upload__")) {
      req(uploaded())
      uploaded()
    } else {
      read_de_dataset(file.path("data", input$dataset))
    }
  })
  de_results <- reactive(dataset()$de_results)

  # Bring-your-own-data drawer wiring. Selecting "Upload your own…" opens the
  # offcanvas; any bundled dataset is remembered so a cancelled upload can fall
  # back to it rather than leaving the app on an empty "__upload__" selection.
  prev_dataset <- reactiveVal(unname(datasets[[1]]))
  observeEvent(input$dataset, {
    if (identical(input$dataset, "__upload__")) {
      session$sendCustomMessage("open_de_upload", TRUE)
    } else {
      prev_dataset(input$dataset)
    }
  })
  observeEvent(input$de_upload_closed, {
    if (identical(input$dataset, "__upload__") && is.null(uploaded())) {
      updateSelectInput(session, "dataset", selected = prev_dataset())
    }
  })

  # --- About this dataset: disease/design, size, source, reference, links ---
  output$dataset_card <- renderUI({
    meta <- dataset()$metadata
    n <- nrow(meta)
    grp <- if ("group" %in% names(meta)) table(meta$group) else NULL
    grp_txt <- if (!is.null(grp)) {
      paste(sprintf("%s (n=%d)", names(grp), as.integer(grp)), collapse = ", ")
    }
    cols <- setdiff(names(meta), "sample")
    info <- dataset_info[[input$dataset]]
    if (is.null(info)) {
      info <- list(
        title = "Your uploaded dataset",
        design = NULL,
        source = "User-provided CSVs (matching the DE data contract)",
        portal = NULL,
        reference = NULL,
        doi = NULL,
        license = NULL
      )
    }
    line <- function(label, value) {
      if (is.null(value)) {
        NULL
      } else {
        tags$p(class = "mb-1", tags$strong(paste0(label, ": ")), value)
      }
    }
    card(
      card_header(info$title),
      card_body(
        class = "small",
        layout_columns(
          col_widths = c(6, 6),
          div(
            line("Design", info$design),
            tags$p(
              class = "mb-1",
              tags$strong("Samples: "),
              n,
              if (!is.null(grp_txt)) paste0(" - ", grp_txt)
            ),
            line("Metadata fields", paste(cols, collapse = ", "))
          ),
          div(
            line("Source", info$source),
            if (!is.null(info$reference)) {
              tags$p(
                class = "mb-1",
                tags$strong("Reference: "),
                info$reference,
                if (!is.null(info$doi)) {
                  tagList(
                    " ",
                    tags$a(
                      href = info$doi,
                      target = "_blank",
                      rel = "noopener",
                      "DOI"
                    )
                  )
                }
              )
            },
            line("License", info$license)
          )
        ),
        div(
          class = "d-flex gap-2 flex-wrap align-items-center mt-1",
          if (!is.null(info$portal)) {
            tags$a(
              href = info$portal,
              target = "_blank",
              rel = "noopener",
              class = "btn btn-sm btn-outline-secondary",
              icon("up-right-from-square"),
              paste0(" ", info$portal_label %||% "Data portal")
            )
          },
          actionLink("goto_about", "Read more on the About page →")
        )
      )
    )
  })
  # Jump to the About tab from the dataset card's link.
  observeEvent(input$goto_about, {
    bslib::nav_select("nav", "About")
  })

  # --- Assistant: scoped, tool-using BYOK chat ----------------------------
  # A plain (non-reactive) mirror of the app's current state. The assistant's
  # tools read it directly, so they are safe to call mid-stream (outside any
  # reactive context); it is kept current by an observer at the end of server().
  chat_state <- new.env(parent = emptyenv())

  # Genes the assistant asked the Heatmap to show (via set_heatmap_genes); NULL
  # means "follow the table selection / top-N seed" as usual.
  agent_heatmap_genes <- reactiveVal(NULL)

  # One shared "focus gene" unifies selection: it drives Gene detail and is
  # cross-highlighted in the Volcano, following the last gene the user clicked in
  # the Results table or the Volcano (default: the most significant gene).
  focus_gene <- reactiveVal(NULL)

  # Hard-scoped: the assistant only helps with THIS app + dataset, reads live
  # state through its tools, and declines anything off-topic.
  de_system_prompt <- paste(
    "You are the DE Explorer assistant, embedded in a differential-expression",
    "app showing one loaded dataset (e.g. TCGA-BRCA tumour vs normal). Your",
    "ONLY job is to help the user explore and interpret THIS app: its current",
    "dataset and its views -- PCA, results table, gene detail, volcano, heatmap,",
    "and MSigDB Hallmark over-representation enrichment.",
    "",
    "Before answering about a view, call the matching read tool for its live",
    "state: dataset_info, describe_pca, results_table, describe_volcano,",
    "describe_heatmap, describe_enrichment. Never invent gene names, counts, or",
    "statistics -- quote the tool output. Explain log2 fold change, adjusted",
    "p-values, PCA, and pathway terms plainly.",
    "",
    "You can also DRIVE the app's controls when the user asks -- then briefly say",
    "what you changed:",
    "- set_dataset: switch the loaded dataset.",
    "- set_thresholds: change the fold-change / significance cutoffs and metric",
    "  (drives the volcano, table, and enrichment together).",
    "- set_pca: change the PCA colour-by column or gene count.",
    "- set_focus_gene: focus a gene in Gene detail (also highlighted in volcano).",
    "- set_heatmap_genes: show specific genes in the heatmap.",
    "- set_heatmap_display: toggle row z-score vs expression, and clustering.",
    "- set_table_filter: show all genes or only significant ones.",
    "- set_volcano_labels: how many top genes the volcano labels.",
    "After changing a control, you may re-read the relevant view to interpret it.",
    "",
    "Refuse anything outside DE Explorer and this dataset: for off-topic or",
    "general questions, briefly decline and point back to what the app can do.",
    "Be concise.",
    sep = "\n"
  )

  # Read/interpret tools over the state mirror (guarded so the app still loads
  # without ellmer). Each returns a compact summary from the Shiny-free helpers
  # in R/_shared/de-summary.R.
  de_tools <- list()
  if (requireNamespace("ellmer", quietly = TRUE)) {
    de_tools <- list(
      ellmer::tool(
        function() {
          de_summarise_dataset(chat_state$dataset, chat_state$dataset_label)
        },
        name = "dataset_info",
        description = paste(
          "Meta on the currently selected dataset: sample and gene counts,",
          "groups, and metadata columns. Use for @dataset."
        )
      ),
      ellmer::tool(
        function() {
          de_summarise_pca(
            chat_state$dataset,
            chat_state$pca_colour,
            chat_state$pca_ntop
          )
        },
        name = "describe_pca",
        description = paste(
          "PCA view summary: variance explained by PC1/PC2 and group",
          "separation along PC1. Use for @pca."
        )
      ),
      ellmer::tool(
        function() {
          de_summarise_table(
            chat_state$dataset$de_results,
            chat_state$lfc,
            chat_state$p,
            chat_state$p_col
          )
        },
        name = "results_table",
        description = paste(
          "Results-table summary: up/down/NS counts and the top up- and",
          "down-regulated genes at the current thresholds. Use for @results."
        )
      ),
      ellmer::tool(
        function() {
          de_summarise_volcano(
            chat_state$dataset$de_results,
            chat_state$lfc,
            chat_state$p,
            chat_state$p_col
          )
        },
        name = "describe_volcano",
        description = paste(
          "Volcano summary: up/down/NS counts, the most significant genes, and",
          "the largest fold changes. Use for @volcano."
        )
      ),
      ellmer::tool(
        function() {
          de_summarise_heatmap(chat_state$dataset, chat_state$heatmap_genes)
        },
        name = "describe_heatmap",
        description = paste(
          "Heatmap summary: which genes are currently shown and the sample",
          "groups they span. Use for @heatmap."
        )
      ),
      ellmer::tool(
        function() {
          de_summarise_enrichment(
            chat_state$dataset$de_results,
            hallmark_sets,
            chat_state$lfc,
            chat_state$p,
            chat_state$p_col
          )
        },
        name = "describe_enrichment",
        description = paste(
          "Enrichment summary: top Hallmark pathways over-represented among the",
          "significant genes. Use for @enrichment."
        )
      ),
      ellmer::tool(
        function(genes) {
          valid <- intersect(genes, chat_state$dataset$de_results$gene)
          if (length(valid) == 0) {
            return(
              "None of those genes are in the current dataset; heatmap unchanged."
            )
          }
          agent_heatmap_genes(valid)
          paste0(
            "Heatmap updated to show ",
            length(valid),
            " gene(s): ",
            paste(valid, collapse = ", "),
            "."
          )
        },
        name = "set_heatmap_genes",
        description = paste(
          "Update the Heatmap to display the given gene symbols from the current",
          "dataset (replaces the shown selection). Use when the user asks to",
          "show or compare specific genes in the heatmap."
        ),
        arguments = list(
          genes = ellmer::type_array(
            items = ellmer::type_string("A gene symbol"),
            description = "Gene symbols to display in the heatmap"
          )
        )
      ),
      # --- Control tools: drive the app's inputs (updateXxxInput and the shared
      # reactiveVals are all safe to call mid-stream, outside a reactive context).
      ellmer::tool(
        function(dataset) {
          choices <- setdiff(unname(datasets), "__upload__")
          if (!dataset %in% choices) {
            return(paste0(
              "Unknown dataset. Choose one of: ",
              toString(choices)
            ))
          }
          updateSelectInput(session, "dataset", selected = dataset)
          paste0("Dataset switched to ", dataset, ".")
        },
        name = "set_dataset",
        description = paste(
          "Switch the loaded dataset. de-brca = TCGA-BRCA breast cancer (tumour",
          "vs normal); de-airway = airway dexamethasone; de-synthetic =",
          "reproducible synthetic set."
        ),
        arguments = list(
          dataset = ellmer::type_enum(
            setdiff(unname(datasets), "__upload__"),
            description = "The dataset id to load"
          )
        )
      ),
      ellmer::tool(
        function(lfc = NULL, p_threshold = NULL, significance_metric = NULL) {
          changed <- character(0)
          if (!is.null(lfc)) {
            lfc <- max(0, min(5, lfc))
            updateSliderInput(session, "lfc", value = lfc)
            changed <- c(changed, paste0("|log2FC| >= ", lfc))
          }
          if (!is.null(p_threshold)) {
            p_threshold <- max(0.001, min(0.1, p_threshold))
            updateSliderInput(session, "p", value = p_threshold)
            changed <- c(changed, paste0("p < ", p_threshold))
          }
          if (!is.null(significance_metric)) {
            updateRadioButtons(session, "pcol", selected = significance_metric)
            changed <- c(
              changed,
              paste0(
                "metric = ",
                if (identical(significance_metric, "padj")) {
                  "adjusted p"
                } else {
                  "raw p"
                }
              )
            )
          }
          if (length(changed) == 0) {
            return("No thresholds given; nothing changed.")
          }
          paste0("Thresholds updated: ", toString(changed), ".")
        },
        name = "set_thresholds",
        description = paste(
          "Change the significance thresholds that drive the volcano, results",
          "table, and enrichment together. Omit any argument to leave it",
          "unchanged. lfc = |log2 fold change| cutoff (0-5); p_threshold =",
          "significance cutoff (0.001-0.1); significance_metric = padj (adjusted)",
          "or pvalue (raw)."
        ),
        arguments = list(
          lfc = ellmer::type_number(
            "The |log2 fold change| cutoff, 0 to 5.",
            required = FALSE
          ),
          p_threshold = ellmer::type_number(
            "The significance cutoff, 0.001 to 0.1.",
            required = FALSE
          ),
          significance_metric = ellmer::type_enum(
            c("padj", "pvalue"),
            description = "Which p-value to threshold on.",
            required = FALSE
          )
        )
      ),
      ellmer::tool(
        function(colour_by = NULL, n_top = NULL) {
          changed <- character(0)
          if (!is.null(colour_by)) {
            cols <- setdiff(names(chat_state$dataset$metadata), "sample")
            if (!colour_by %in% cols) {
              return(paste0(
                "Unknown column. This dataset's metadata columns: ",
                toString(cols)
              ))
            }
            updateSelectInput(session, "pca_colour", selected = colour_by)
            changed <- c(changed, paste0("colour by ", colour_by))
          }
          if (!is.null(n_top)) {
            n_top <- as.character(n_top)
            choices <- c("100", "250", "500", "All")
            if (!n_top %in% choices) {
              return(paste0("n_top must be one of: ", toString(choices)))
            }
            updateSelectInput(session, "pca_ntop", selected = n_top)
            changed <- c(changed, paste0(n_top, " most-variable genes"))
          }
          if (length(changed) == 0) {
            return("Nothing to change for PCA.")
          }
          paste0("PCA updated: ", toString(changed), ".")
        },
        name = "set_pca",
        description = paste(
          "Change the PCA view: colour_by is a metadata column to colour samples",
          "by; n_top is how many most-variable genes to use (100, 250, 500, or",
          "All). Either may be omitted."
        ),
        arguments = list(
          colour_by = ellmer::type_string(
            "Metadata column to colour PCA points by.",
            required = FALSE
          ),
          n_top = ellmer::type_string(
            "Most-variable gene count: 100, 250, 500, or All.",
            required = FALSE
          )
        )
      ),
      ellmer::tool(
        function(gene) {
          if (!gene %in% chat_state$dataset$de_results$gene) {
            return(paste0("'", gene, "' is not in the current dataset."))
          }
          focus_gene(gene)
          paste0("Gene detail now focuses ", gene, ".")
        },
        name = "set_focus_gene",
        description = paste(
          "Focus a single gene in the Gene detail view (its expression by",
          "group); the gene is also highlighted in the volcano. Use when the user",
          "asks to look at one specific gene."
        ),
        arguments = list(
          gene = ellmer::type_string("A gene symbol from the current dataset")
        )
      ),
      ellmer::tool(
        function(scale = NULL, cluster = NULL) {
          changed <- character(0)
          if (!is.null(scale)) {
            updateRadioButtons(session, "hscale", selected = scale)
            changed <- c(
              changed,
              paste0(
                "values = ",
                if (identical(scale, "row")) "row z-score" else "expression"
              )
            )
          }
          if (!is.null(cluster)) {
            updateCheckboxInput(session, "hcluster", value = cluster)
            changed <- c(
              changed,
              paste0("clustering ", if (isTRUE(cluster)) "on" else "off")
            )
          }
          if (length(changed) == 0) {
            return("Nothing to change for the heatmap display.")
          }
          paste0("Heatmap display updated: ", toString(changed), ".")
        },
        name = "set_heatmap_display",
        description = paste(
          "Change how the heatmap renders: scale is 'row' (z-score each gene) or",
          "'none' (raw expression); cluster reorders rows by similarity. Either",
          "may be omitted."
        ),
        arguments = list(
          scale = ellmer::type_enum(
            c("row", "none"),
            description = "Row z-score ('row') or raw expression ('none').",
            required = FALSE
          ),
          cluster = ellmer::type_boolean(
            "Whether to cluster (reorder) the heatmap rows.",
            required = FALSE
          )
        )
      ),
      ellmer::tool(
        function(significant_only) {
          updateCheckboxInput(session, "sigonly", value = significant_only)
          paste0(
            "Results table now shows ",
            if (isTRUE(significant_only)) "only significant" else "all",
            " genes."
          )
        },
        name = "set_table_filter",
        description = paste(
          "Filter the results table: TRUE shows only significant genes at the",
          "current thresholds; FALSE shows all genes."
        ),
        arguments = list(
          significant_only = ellmer::type_boolean(
            "Show only significant genes?"
          )
        )
      ),
      ellmer::tool(
        function(max_labels) {
          max_labels <- as.integer(max(0, min(30, max_labels)))
          updateSliderInput(session, "topn", value = max_labels)
          paste0("Volcano now labels up to ", max_labels, " top genes.")
        },
        name = "set_volcano_labels",
        description = paste(
          "Set how many of the top genes the volcano plot labels (0 to 30)."
        ),
        arguments = list(
          max_labels = ellmer::type_integer(
            "Number of top genes to label, 0 to 30."
          )
        )
      )
    )
  }

  byok_chat_server(
    "chat",
    system_prompt = de_system_prompt,
    tools = de_tools
  )

  # --- Enrichment: Hallmark pathways over-represented in the DE hits -------
  # One computation feeds both the dot plot and the table.
  enrichment_res <- reactive({
    dr <- de_results()
    status <- de_status(dr$logFC, dr[[input$pcol]], input$lfc, input$p)
    enrichment_ora(
      hits = dr$gene[status != "NS"],
      gene_sets = hallmark_sets,
      universe = dr$gene
    )
  })

  # Dot plot: the classic enrichment view -- gene ratio (fraction of the set that
  # are hits) on x, overlap size as the dot size, adjusted-p as the colour, top
  # sets by significance. Reads better at a glance than the table alone.
  output$enrichment_dot <- renderPlot({
    res <- enrichment_res()
    shiny::validate(shiny::need(
      nrow(res) > 0,
      "No enriched Hallmark sets (need gene symbols overlapping Hallmark)."
    ))
    top <- utils::head(res[order(res$p_adj), , drop = FALSE], 15)
    top$gene_ratio <- top$n_hits / top$set_size
    # Tidy the Hallmark labels (drop the HALLMARK_ prefix, underscores -> spaces).
    top$label <- tolower(gsub("_", " ", sub("^HALLMARK_", "", top$gene_set)))
    top$label <- factor(top$label, levels = rev(top$label[order(top$p_adj)]))
    ggplot2::ggplot(
      top,
      ggplot2::aes(x = gene_ratio, y = label)
    ) +
      ggplot2::geom_point(ggplot2::aes(size = n_hits, colour = p_adj)) +
      ggplot2::scale_colour_gradientn(
        colours = ltc_gradient(),
        trans = "reverse",
        name = "adj. p"
      ) +
      ggplot2::scale_size_continuous(name = "overlap", range = c(3, 11)) +
      ggplot2::labs(x = "gene ratio (hits / set size)", y = NULL) +
      ggplot2::theme_minimal(base_size = 16) +
      ggplot2::theme(panel.grid.minor = ggplot2::element_blank())
  })

  output$enrichment <- DT::renderDT(
    {
      res <- enrichment_res()
      shiny::validate(shiny::need(
        nrow(res) > 0,
        "No enriched Hallmark sets (need gene symbols overlapping Hallmark)."
      ))
      DT::datatable(
        res,
        rownames = FALSE,
        selection = "none",
        class = "cell-border stripe hover",
        extensions = "Buttons",
        options = list(
          dom = "Bfrtip",
          buttons = list("copy", "csv"),
          pageLength = 15
        )
      )
    },
    server = TRUE
  )

  # --- Gene detail: the focused gene's expression by group ----------------
  # Default the focus to the most significant gene whenever the dataset loads.
  observeEvent(de_results(), {
    dr <- de_results()
    focus_gene(dr$gene[order(dr$padj, na.last = TRUE)][1])
  })
  output$detail_gene_label <- renderUI({
    g <- focus_gene()
    if (is.null(g)) {
      return(tags$p(
        class = "text-muted small mb-2",
        "Click a gene in the Results table or the Volcano."
      ))
    }
    tags$p(
      class = "mb-2",
      "Showing ",
      tags$strong(g),
      tags$span(
        class = "text-muted small",
        " - click another table row or volcano point to change."
      )
    )
  })
  group_comparison_server(
    "gdetail",
    values = reactive({
      g <- req(focus_gene())
      m <- de_expression_matrix(dataset())
      req(g %in% rownames(m))
      m[g, ]
    }),
    metadata = reactive(dataset()$metadata),
    value_label = reactive(paste(req(focus_gene()), "expression")),
    group_col = reactive("group")
  )

  # --- Volcano (click a point to focus that gene) --------------------------
  vol <- volcano_server(
    "volcano",
    de_results = de_results,
    lfc_threshold = reactive(input$lfc),
    p_threshold = reactive(input$p),
    p_col = reactive(input$pcol),
    label_top_n = reactive(input$topn),
    highlight = reactive(focus_gene())
  )
  observeEvent(vol$clicked(), {
    g <- vol$clicked()
    if (!is.null(g)) {
      focus_gene(g)
    }
  })

  # --- Results table (row selection is the shared gene selection) ----------
  table_res <- gene_table_server(
    "table",
    de_results = de_results,
    lfc_threshold = reactive(input$lfc),
    p_threshold = reactive(input$p),
    p_col = reactive(input$pcol),
    sig_only = reactive(input$sigonly)
  )
  # Clicking a table row focuses that gene in Gene detail + the Volcano.
  observeEvent(table_res$clicked(), {
    g <- table_res$clicked()
    if (!is.null(g)) {
      focus_gene(g)
    }
  })

  # Clear the table's row selection when the dataset changes, so the heatmap is
  # never driven by row indices that pointed into the previous dataset (DT keeps
  # the prior selection until its client re-render). The module's DT output is
  # at the "table" namespace, hence "table-tbl".
  observeEvent(input$dataset, {
    DT::selectRows(DT::dataTableProxy("table-tbl"), NULL)
    agent_heatmap_genes(NULL)
  })

  # When the user drives the table selection, hand the heatmap back to them:
  # drop any gene set the assistant had pushed via set_heatmap_genes.
  observeEvent(
    table_res$selected(),
    agent_heatmap_genes(NULL),
    ignoreInit = TRUE
  )

  # Genes feeding the heatmap: the table's selection (intersected with the
  # current dataset's genes, so a stale or out-of-range selection can't drive or
  # error the heatmap), else the top-N by the chosen significance metric so the
  # heatmap is never empty.
  selected_genes <- reactive({
    sel <- intersect(table_res$selected(), de_results()$gene)
    if (length(sel) > 0) {
      return(sel)
    }
    dr <- de_results()
    utils::head(
      dr$gene[order(dr[[input$pcol]], na.last = TRUE)],
      default_heatmap_n
    )
  })

  # --- Heatmap -------------------------------------------------------------
  # The gene-selector is seeded from the shared selection -- the assistant's
  # pushed genes (set_heatmap_genes) take precedence, else the table rows /
  # top-N -- and is then the source of truth for the heatmap rows, so users can
  # refine the gene set or paste their own; it falls back to the seed when
  # cleared.
  heat_genes <- gene_selector_server(
    "heatgenes",
    choices = reactive(de_results()$gene),
    selected = reactive({
      ag <- agent_heatmap_genes()
      if (!is.null(ag)) ag else selected_genes()
    })
  )
  # Intersect the selectize's picks with the current dataset's genes: on a
  # dataset switch the selectize still holds the previous dataset's genes for a
  # round-trip, which would otherwise be passed straight to (and error) the
  # heatmap. Fall back to the seed set when nothing valid is picked.
  heatmap_rows <- reactive({
    picked <- intersect(heat_genes(), de_results()$gene)
    if (length(picked) > 0) picked else selected_genes()
  })
  heatmap_server(
    "heat",
    matrix = reactive(de_expression_matrix(dataset())),
    rows = heatmap_rows,
    metadata = reactive(dataset()$metadata),
    scale = reactive(input$hscale),
    cluster_rows = reactive(input$hcluster)
  )

  # --- PCA -----------------------------------------------------------------
  # Colour-by choices depend on the dataset's metadata (group/batch vs cell).
  output$pca_colour_ui <- renderUI({
    cols <- setdiff(names(dataset()$metadata), "sample")
    selectInput("pca_colour", "Colour samples by", choices = cols)
  })
  pca_server(
    "pca",
    dataset = dataset,
    colour_by = reactive(input$pca_colour),
    n_top = reactive(
      if (identical(input$pca_ntop, "All")) NULL else as.integer(input$pca_ntop)
    )
  )

  # --- Keep the assistant's state mirror current --------------------------
  # Reads reactives in a reactive context and writes plain values into the env
  # the assistant tools read (see the tool definitions above).
  observe({
    chat_state$dataset <- dataset()
    chat_state$dataset_label <- names(datasets)[match(input$dataset, datasets)]
    chat_state$lfc <- input$lfc
    chat_state$p <- input$p
    chat_state$p_col <- input$pcol
    chat_state$pca_colour <- input$pca_colour %||% "group"
    chat_state$pca_ntop <- if (identical(input$pca_ntop, "All")) {
      NULL
    } else {
      as.integer(input$pca_ntop)
    }
    chat_state$heatmap_genes <- heatmap_rows()
  })
}

shinyApp(ui, server)
